import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

#define BLOCK_SIZE 512

__global__ __launch_bounds__(BLOCK_SIZE, 2) void triplet_margin_loss_kernel(
    const float* __restrict__ anchor,
    const float* __restrict__ positive,
    const float* __restrict__ negative,
    float* __restrict__ loss_sum,
    int batch_size,
    int dim,
    float margin)
{
    __shared__ float spos[BLOCK_SIZE / 32];
    __shared__ float sneg[BLOCK_SIZE / 32];
    __shared__ float block_acc;
    int tid = threadIdx.x;
    if (tid == 0) block_acc = 0.0f;
    __syncthreads();
    int dim4 = dim / 4;
    // Grid-stride loop over rows: each block processes multiple rows and
    // accumulates a local block-level sum, issuing only ONE atomicAdd per
    // block instead of one per row. This drastically reduces atomic
    // contention on loss_sum when batch_size is much larger than the
    // number of blocks launched.
    for (int row = blockIdx.x; row < batch_size; row += gridDim.x) {
        const float* a = anchor + (size_t)row * dim;
        const float* p = positive + (size_t)row * dim;
        const float* n = negative + (size_t)row * dim;
        float sum_pos = 0.0f;
        float sum_neg = 0.0f;
        const float4* a4 = reinterpret_cast<const float4*>(a);
        const float4* p4 = reinterpret_cast<const float4*>(p);
        const float4* n4 = reinterpret_cast<const float4*>(n);
        #pragma unroll 4
        for (int i = tid; i < dim4; i += blockDim.x) {
            float4 av = __ldg(&a4[i]);
            float4 pv = __ldg(&p4[i]);
            float4 nv = __ldg(&n4[i]);
            float dax = av.x - pv.x;
            float day = av.y - pv.y;
            float daz = av.z - pv.z;
            float daw = av.w - pv.w;
            float dnx = av.x - nv.x;
            float dny = av.y - nv.y;
            float dnz = av.z - nv.z;
            float dnw = av.w - nv.w;
            sum_pos += dax * dax + day * day + daz * daz + daw * daw;
            sum_neg += dnx * dnx + dny * dny + dnz * dnz + dnw * dnw;
        }
        #pragma unroll 4
        for (int i = dim4 * 4 + tid; i < dim; i += blockDim.x) {
            float av = __ldg(&a[i]);
            float da = av - __ldg(&p[i]);
            float dn = av - __ldg(&n[i]);
            sum_pos += da * da;
            sum_neg += dn * dn;
        }
        // Warp-level reduction using shuffle intrinsics to minimize synchronization
        for (int offset = 16; offset > 0; offset >>= 1) {
            sum_pos += __shfl_down_sync(0xffffffff, sum_pos, offset);
            sum_neg += __shfl_down_sync(0xffffffff, sum_neg, offset);
        }
        int lane = tid & 31;
        int wid = tid >> 5;
        if (lane == 0) {
            spos[wid] = sum_pos;
            sneg[wid] = sum_neg;
        }
        __syncthreads();
        if (wid == 0) {
            int num_warps = blockDim.x / 32;
            float sp = (lane < num_warps) ? spos[lane] : 0.0f;
            float sn = (lane < num_warps) ? sneg[lane] : 0.0f;
            for (int offset = 16; offset > 0; offset >>= 1) {
                sp += __shfl_down_sync(0xffffffff, sp, offset);
                sn += __shfl_down_sync(0xffffffff, sn, offset);
            }
            if (lane == 0) {
                float dist_pos = sqrtf(sp);
                float dist_neg = sqrtf(sn);
                float l = dist_pos - dist_neg + margin;
                l = l > 0.0f ? l : 0.0f;
                block_acc += l;
            }
        }
        __syncthreads();
    }
    // Each block writes its own partial sum directly to global memory,
    // avoiding atomic contention entirely. A separate lightweight
    // reduction kernel later combines these per-block partial sums.
    if (tid == 0) {
        loss_sum[blockIdx.x] = block_acc;
    }
}
__global__ void reduce_partial_sums_kernel(
    const float* __restrict__ partial,
    float* __restrict__ out,
    int n,
    int batch_size)
{
    __shared__ float sdata[256];
    int tid = threadIdx.x;
    float sum = 0.0f;
    for (int i = tid; i < n; i += blockDim.x) {
        sum += partial[i];
    }
    sdata[tid] = sum;
    __syncthreads();
    for (int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (tid < s) {
            sdata[tid] += sdata[tid + s];
        }
        __syncthreads();
    }
    if (tid == 0) {
        out[0] = sdata[0] / static_cast<float>(batch_size);
    }
}

torch::Tensor triplet_margin_loss_cuda(
    torch::Tensor anchor,
    torch::Tensor positive,
    torch::Tensor negative,
    double margin)
{
    TORCH_CHECK(anchor.is_cuda(), "anchor must be a CUDA tensor");
    TORCH_CHECK(positive.is_cuda(), "positive must be a CUDA tensor");
    TORCH_CHECK(negative.is_cuda(), "negative must be a CUDA tensor");

    anchor = anchor.contiguous();
    positive = positive.contiguous();
    negative = negative.contiguous();

    int batch_size = anchor.size(0);
    int dim = anchor.size(1);

    int num_blocks = batch_size < 8192 ? batch_size : 8192;
    auto partial_sums = torch::empty({num_blocks}, anchor.options());
    auto loss_out = torch::zeros({1}, anchor.options());
    dim3 grid(num_blocks);
    dim3 block(BLOCK_SIZE);
    triplet_margin_loss_kernel<<<grid, block>>>(
        anchor.data_ptr<float>(),
        positive.data_ptr<float>(),
        negative.data_ptr<float>(),
        partial_sums.data_ptr<float>(),
        batch_size,
        dim,
        static_cast<float>(margin)
    );
    reduce_partial_sums_kernel<<<1, 256>>>(
        partial_sums.data_ptr<float>(),
        loss_out.data_ptr<float>(),
        num_blocks,
        batch_size
    );
    return loss_out.squeeze();
}
"""

